  arguments[0] = 99;
  return a;
}
function strict(a) {
  'use strict';
  arguments[0] = 99;
  return a;
}
sloppy(1); // 99
strict(1); // 1

function sum(...nums) {
  return nums.reduce((s, n) => s + n, 0);
